      select.appendChild(opt);
    });
    document.getElementById("totalSlidesNum").textContent = SLIDES.length;
  }

  function renderSlide(index) {
    if (index < 0) index = 0;
    if (index >= SLIDES.length) index = SLIDES.length - 1;
    currentSlideIndex = index;

    const slide = SLIDES[index];
    const card = document.getElementById("presCard");
    card.style.setProperty("--pres-font-size", currentBaseFontSize + "px");

    document.getElementById("presBadgeSection").textContent = slide.badge;
    document.getElementById("currentSlideNum").textContent = index + 1;
    document.getElementById("slideSelect").value = index;

    card.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <span class="pres-slide-tag ${slide.tag}">${slide.tagText}</span>
        <span style="font-size:0.85em; opacity:0.8; font-weight:700;">Konu ${index + 1} / ${SLIDES.length}</span>
      </div>
      <div>
        <h2>${slide.title}</h2>
        ${slide.subtitle ? `<div style="font-size:1.05em; opacity:0.85; margin-top:4px; font-weight:600;">${slide.subtitle}</div>` : ''}
      </div>
      ${slide.html}
    `;

    document.getElementById("prevBtn").disabled = (index === 0);
    document.getElementById("nextBtn").disabled = (index === SLIDES.length - 1);
  }

  function openPresentation(index) {
    initPresentation();
    renderSlide(index || 0);
    document.getElementById("presentationModal").classList.add("active");
    document.body.style.overflow = "hidden";
  }

  function closePresentation() {
    document.getElementById("presentationModal").classList.remove("active");
    document.body.style.overflow = "auto";
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(() => {});
    }
  }

  function nextSlide() {
    if (currentSlideIndex < SLIDES.length - 1) {
      renderSlide(currentSlideIndex + 1);
    }
  }

  function prevSlide() {
    if (currentSlideIndex > 0) {
      renderSlide(currentSlideIndex - 1);
    }
  }

  function jumpToSlide(idx) {
    renderSlide(parseInt(idx, 10));
  }

  function adjustFontSize(delta) {
    currentBaseFontSize = Math.max(16, Math.min(38, currentBaseFontSize + delta));
    const card = document.getElementById("presCard");
    if (card) {
      card.style.setProperty("--pres-font-size", currentBaseFontSize + "px");
    }
  }

  function togglePresentationTheme() {
    isDarkTheme = !isDarkTheme;
    const modal = document.getElementById("presentationModal");
    const btn = document.getElementById("themeToggleBtn");
    if (!isDarkTheme) {
      modal.classList.add("theme-light");
      btn.innerHTML = "🌙 Koyu Tema";
    } else {
      modal.classList.remove("theme-light");
      btn.innerHTML = "☀️ Açık Tema";
    }
  }

  function toggleNativeFullscreen() {
    try {
      if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type: 'REQUEST_FULLSCREEN' }, '*');
      }
    } catch (e) {}
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => {
        document.getElementById("fsIcon").textContent = "🗗";
        document.getElementById("fsText").textContent = "Pencere";
      }).catch(err => {
        console.log("Fullscreen request failed", err);
      });
    } else {
      document.exitFullscreen().then(() => {
        document.getElementById("fsIcon").textContent = "⛶";
        document.getElementById("fsText").textContent = "Tam Ekran";
      }).catch(() => {});
    }
  }

  // Keyboard navigation
  window.addEventListener("keydown", (e) => {
    const modal = document.getElementById("presentationModal");
    if (!modal.classList.contains("active")) return;

    if (e.key === "ArrowRight" || e.key === " " || e.key === "PageDown") {
      e.preventDefault();
      nextSlide();
    } else if (e.key === "ArrowLeft" || e.key === "PageUp") {
      e.preventDefault();
      prevSlide();
    } else if (e.key === "Escape") {
      closePresentation();
    } else if (e.key === "f" || e.key === "F") {
      toggleNativeFullscreen();
    } else if (e.key === "+" || e.key === "=") {
      adjustFontSize(2);
    } else if (e.key === "-" || e.key === "_") {
      adjustFontSize(-2);
    }
  });

  // Touch Swipe for Smart Board
  let touchStartX = 0;
  let touchEndX = 0;
  const slideContainer = document.getElementById("slideContainer");
  if (slideContainer) {
    slideContainer.addEventListener("touchstart", (e) => {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });
    slideContainer.addEventListener("touchend", (e) => {
      touchEndX = e.changedTouches[0].screenX;
      handleSwipe();
    }, { passive: true });
  }

  function handleSwipe() {
    const swipeDistance = touchEndX - touchStartX;
    if (swipeDistance < -50) {
      nextSlide();
    } else if (swipeDistance > 50) {
      prevSlide();
    }
  }

  window.addEventListener("DOMContentLoaded", () => {
    initPresentation();
  });

// Bridge for parent Next.js page
window.addEventListener('message', function(e) {
  if (e.data && (e.data.type === 'TRIGGER_FIRST_SECTION_FOCUS' || e.data.type === 'OPEN_PRESENTATION')) {
    if (typeof openPresentation === 'function') {
      openPresentation(0);
    }
  }
});
</script>

